// Pre-rendered schematic PNGs (generated by shorts/block-images.mjs into public/block-img/).
// Used for per-block og:image and the image sitemap — theme-independent surfaces only; the
// on-page schematic stays live SVG so the Light/Mid/Dark themes keep working. Server-only.
import { existsSync } from "node:fs";
import { join } from "node:path";

export function blockImage(slug: string): string | null {
  return existsSync(join(process.cwd(), "public", "block-img", `${slug}.png`))
    ? `https://www.electrace.net/block-img/${slug}.png`
    : null;
}
